def transform(grid):
    h, w = len(grid), len(grid[0])

    full_rows = [r for r in range(h) if all(v == 3 for v in grid[r])]
    full_cols = [c for c in range(w) if all(grid[r][c] == 3 for r in range(h))]

    horizontal = bool(full_rows)
    if horizontal:
        band_start = min(full_rows)
        t = len(full_rows)
    else:
        band_start = min(full_cols)
        t = len(full_cols)

    stride = t + 1
    out = [[0 if v == 3 else v for v in row] for row in grid]

    # Find the repeated tile motif from the unmasked portions.
    motifs = {}
    for r0 in range(0, h, stride):
        for c0 in range(0, w, stride):
            if horizontal and band_start <= r0 < band_start + t:
                continue
            if not horizontal and band_start <= c0 < band_start + t:
                continue
            if r0 + t > h or c0 + t > w:
                continue
            motif = tuple(
                tuple(2 if grid[r0 + i][c0 + j] == 2 else 0 for j in range(t))
                for i in range(t)
            )
            if any(v == 2 for row in motif for v in row):
                motifs[motif] = motifs.get(motif, 0) + 1

    if not motifs:
        return out
    pattern = max(motifs, key=motifs.get)

    # Restore tiles hidden by the 3 band wherever the band-indexed
    # cell of the motif is occupied.
    if horizontal:
        br = band_start // stride
        for bc in range((w + stride - 1) // stride):
            if br < t and bc < t and pattern[br][bc] == 2:
                r0, c0 = br * stride, bc * stride
                for i in range(t):
                    for j in range(t):
                        if r0 + i < h and c0 + j < w:
                            out[r0 + i][c0 + j] = pattern[i][j]
    else:
        bc = band_start // stride
        for br in range((h + stride - 1) // stride):
            if br < t and bc < t and pattern[br][bc] == 2:
                r0, c0 = br * stride, bc * stride
                for i in range(t):
                    for j in range(t):
                        if r0 + i < h and c0 + j < w:
                            out[r0 + i][c0 + j] = pattern[i][j]

    # Mark each tile with the 8 at the motif coordinate corresponding
    # to that tile's position in the array.
    for r0 in range(0, h, stride):
        for c0 in range(0, w, stride):
            if r0 + t > h or c0 + t > w:
                continue
            br, bc = r0 // stride, c0 // stride
            if br >= t or bc >= t:
                continue
            present = any(out[r0 + i][c0 + j] == 2
                          for i in range(t) for j in range(t))
            if present and pattern[br][bc] == 2:
                out[r0 + br][c0 + bc] = 8

    return out
